<?php
require_once '../../config/auth.php';
requestMethod('GET');
requireAdmin();
try{ $db=getDB(); $scalar=function($sql)use($db){return $db->query($sql)->fetchColumn();}; $overview=['total_users'=>(int)$scalar('SELECT COUNT(*) FROM users'),'pending_listings'=>(int)$scalar("SELECT COUNT(*) FROM listings WHERE status='pending'"),'new_reports'=>(int)$scalar("SELECT COUNT(*) FROM reports WHERE status='new'"),'published_listings'=>(int)$scalar("SELECT COUNT(*) FROM listings WHERE status='published'"),'total_reviews'=>(int)$scalar('SELECT COUNT(*) FROM landlord_reviews'),'avg_rating'=>(float)($scalar('SELECT COALESCE(AVG(star_rating),0) FROM landlord_reviews WHERE is_approved=1'))]; $districts=$db->query("SELECT COALESCE(d.name,'Unknown') AS label, COUNT(*) AS value FROM listings l LEFT JOIN districts d ON d.id=l.district_id WHERE l.status<>'deleted' GROUP BY d.name ORDER BY value DESC LIMIT 10")->fetchAll(); $users=$db->query("SELECT DATE_FORMAT(created_at,'%Y-%m') AS label, COUNT(*) AS value FROM users WHERE created_at >= DATE_SUB(CURDATE(), INTERVAL 12 MONTH) GROUP BY DATE_FORMAT(created_at,'%Y-%m') ORDER BY label ASC")->fetchAll(); $types=$db->query("SELECT property_type AS label, COUNT(*) AS value FROM listings WHERE status<>'deleted' GROUP BY property_type")->fetchAll(); jsonResponse(['success'=>true,'stats'=>$overview,'overview'=>$overview,'charts'=>['districts'=>$districts,'users'=>$users,'types'=>$types]]); }catch(Throwable $e){ jsonError('Could not fetch stats.',500); }
